	set(&ch.HelpAutostartLong, "Synced Always-on preference (Start Trim with your IDE).\n\n  trim autostart status\n  trim autostart enable\n  trim autostart disable\n\nenable turns the preference on and best-effort registers OS logon:\n  macOS launchd · Linux systemd --user · Windows Startup Run → %LOCALAPPDATA%\\Trim\\bin (no Administrator on a normal PC)\n\nIf OS registration fails, your preference stays on. The CLI prints a yellow warning, muted guidance, and next steps (trim start / IDE). Use -v for raw OS detail.\n\nPrefer this over trim daemon for everyday use.\nDocs: https://use-trim.com/docs/cli/autostart")
	set(&ch.HelpAutostartEnableShort, "Enable auto-start and best-effort OS logon (Windows Startup Run → LocalAppData, no admin)")
	set(&ch.HelpAutostartDisableShort, "Disable auto-start and uninstall OS logon when supported")

	// Prefer site_messages for root/config help so Admin DB edits win after sync.
	// Offline empty chrome still gets Segmented Allowlist Deep + cursor-link guidance.
	set(&ch.HelpRootLong, "Trim keeps a local Fast Mode proxy on your machine so IDE traffic uses less noisy context.\n\nEveryday: start, stop, status, stats, upgrade, autostart, cursor-link, login, logout, uninstall, setup, version\nAdvanced: tui, compress, daemon, telemetry, config (get | set | sync | rates | models)\n\nFast vs Deep (new accounts default to Deep = Fast then Segmented Allowlist Deep on each last-user prose island in place, order preserved beside paths):\n  trim config get default-tier\n  trim config set default-tier deep\n  trim config set default-tier fast\n  trim config rates\n  trim config set compression-rate 0.7\n  trim config models\n  trim config set deep-v2-backbone mbert-base\n  trim config sync\n\nDeep keep-rate (after/before, Microsoft LLMLingua): Dashboard slider or trim config rates / set compression-rate (billing min/max/step).\nDeep Base Model (Microsoft LLMLingua-2): Dashboard picker or trim config models / set deep-v2-backbone (billing catalog; default mbert-base, optional xlm-roberta-large).\n\nOne-time Deep deps on this PC (not Trim cloud):\n  trim compress --bootstrap\n\nCursor Agent: trim cursor-link enable → trim start → trim cursor-link url (paste HTTPS …/v1; not 127.0.0.1).\n\nSimple savings check after trim start:\n  trim stats\n  open http://127.0.0.1:<port>/dashboard → Show savings detail\n\ntrim status = cloud quota. trim stats = local Deep status / savings meter.\n\nFull remove: trim uninstall (stops Trim processes, deletes local data/binary, and auto-removes npm/Scoop/Homebrew/winget installs when detected).\n\nRun \"trim help <command>\" for details. Prefer trim start / autostart for daily use (new accounts default Deep = Fast then Segmented Allowlist Deep on the live proxy). Use trim compress --bootstrap once, then trim compress --deep for file/batch.")
	set(&ch.DeepBootstrapReqs, "Installing Deep Mode dependencies on this machine (not in Trim cloud)…")
	set(&ch.DeepBootstrapPip, "Installing Deep Mode dependencies on this machine (not in Trim cloud)…")
	set(&ch.DeepBootstrapOk, "Deep Mode dependencies installed on this machine")
